1	import { Component, effect, inject, signal } from '@angular/core';
2	import { AbstractControl, FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
3	import { Pools } from '../../core/pools';
4	import { Session } from '../../core/session';
5	import { Grade } from '../../core/people';
6	import {
7	  LATE_PCT, LIMIT, PERM_ACTIONS, PERM_ROLES, POLICY_DATE, PermAction, ROLES, STANDING_PERMISSIONS, TERMS, Role, RoleName,
8	  SheetSettings,
9	} from '../../core/settings';
10	
11	// The sheet's settings (the clerk limit, the cap, the proof threshold, the proof threshold per grade, the note threshold, the floor, the terms, the grace days per grade, the late percent, the policy date, period numbering from, the grace days, the entry date, the pot and the permission matrix) and the roles it gives user names: clerk, the default for
12	// any name, steward, or viewer (who may change nothing). The settings that carry a figure are dated: each is saved from a from-date
13	// (blank: the sheet's today), and what shows in force is the value on the sheet's today.
14	@Component({
15	  selector: 'app-settings-form',
16	  imports: [ReactiveFormsModule],
17	  template: `
18	    <section aria-labelledby="settings-heading">
19	      <h2 id="settings-heading">Settings</h2>
20	      <form data-testid="settings-form" [formGroup]="settingsForm" (ngSubmit)="saveSettings()">
21	        <label for="setting-clerk-limit">Clerk limit</label>
22	        <input id="setting-clerk-limit" data-testid="setting-clerk-limit" formControlName="clerkLimit"
23	               inputmode="decimal" />
24	        <label for="setting-clerk-limit-from">Clerk limit from (blank: today)</label>
25	        <input id="setting-clerk-limit-from" data-testid="setting-clerk-limit-from" type="date" formControlName="clerkLimitFrom" />
26	        <label for="setting-cap">Cap on a person's due-total (blank: none)</label>
27	        <input id="setting-cap" data-testid="setting-cap" formControlName="cap" inputmode="decimal" />
28	        <label for="setting-cap-from">Cap from (blank: today)</label>
29	        <input id="setting-cap-from" data-testid="setting-cap-from" type="date" formControlName="capFrom" />
30	        <label for="setting-proof-threshold">Proof threshold (a claim due above it needs a proof; blank: none)</label>
31	        <input id="setting-proof-threshold" data-testid="setting-proof-threshold" formControlName="proofThreshold"
32	               inputmode="decimal" />
33	        <label for="setting-proof-threshold-from">Proof threshold from (blank: today)</label>
34	        <input id="setting-proof-threshold-from" data-testid="setting-proof-threshold-from" type="date"
35	               formControlName="proofThresholdFrom" />
36	        <fieldset formGroupName="gradeProofThresholds">
37	          <legend>Proof threshold per grade (blank: the sheet's proof threshold)</legend>
38	          @for (g of grades; track g) {
39	            <label [for]="'setting-proof-threshold-' + g">Grade {{ g }} proof threshold</label>
40	            <input [id]="'setting-proof-threshold-' + g" [attr.data-testid]="'setting-proof-threshold-' + g"
41	                   [formControlName]="g" inputmode="decimal" />
42	            <label [for]="'setting-proof-threshold-' + g + '-from'">Grade {{ g }} proof threshold from (blank: today)</label>
43	            <input [id]="'setting-proof-threshold-' + g + '-from'" [attr.data-testid]="'setting-proof-threshold-' + g + '-from'"
44	                   type="date" [formControlName]="g + 'From'" />
45	          }
46	        </fieldset>
47	        <label for="setting-note-threshold">Note threshold (a claim due above it needs a note to be opened; blank: none)</label>
48	        <input id="setting-note-threshold" data-testid="setting-note-threshold" formControlName="noteThreshold"
49	               inputmode="decimal" />
50	        <label for="setting-note-threshold-from">Note threshold from (blank: today)</label>
51	        <input id="setting-note-threshold-from" data-testid="setting-note-threshold-from" type="date"
52	               formControlName="noteThresholdFrom" />
53	        <label for="setting-floor">Floor</label>
54	        <input id="setting-floor" data-testid="setting-floor" formControlName="floor" inputmode="decimal" />
55	        <label for="setting-floor-from">Floor from (blank: today)</label>
56	        <input id="setting-floor-from" data-testid="setting-floor-from" type="date" formControlName="floorFrom" />
57	        <label for="setting-terms">Terms (business days)</label>
58	        <input id="setting-terms" data-testid="setting-terms" formControlName="terms" inputmode="numeric" />
59	        <label for="setting-terms-from">Terms from (blank: today)</label>
60	        <input id="setting-terms-from" data-testid="setting-terms-from" type="date" formControlName="termsFrom" />
61	        <fieldset formGroupName="gradeTerms">
62	          <legend>Terms per grade (days; blank: the sheet's terms)</legend>
63	          @for (g of grades; track g) {
64	            <label [for]="'setting-terms-' + g">Grade {{ g }}</label>
65	            <input [id]="'setting-terms-' + g" [attr.data-testid]="'setting-terms-' + g" [formControlName]="g"
66	                   inputmode="numeric" />
67	            <label [for]="'setting-terms-' + g + '-from'">Grade {{ g }} terms from (blank: today)</label>
68	            <input [id]="'setting-terms-' + g + '-from'" [attr.data-testid]="'setting-terms-' + g + '-from'"
69	                   type="date" [formControlName]="g + 'From'" />
70	          }
71	        </fieldset>
72	        <fieldset formGroupName="gradeGraces">
73	          <legend>Grace days per grade (a claim is overdue only once its due-by plus them is before today; blank: none)</legend>
74	          @for (g of grades; track g) {
75	            <label [for]="'setting-grace-' + g">Grade {{ g }} grace days</label>
76	            <input [id]="'setting-grace-' + g" [attr.data-testid]="'setting-grace-' + g" [formControlName]="g"
77	                   inputmode="numeric" />
78	            <label [for]="'setting-grace-' + g + '-from'">Grade {{ g }} grace days from (blank: today)</label>
79	            <input [id]="'setting-grace-' + g + '-from'" [attr.data-testid]="'setting-grace-' + g + '-from'"
80	                   type="date" [formControlName]="g + 'From'" />
81	          }
82	        </fieldset>
83	        <label for="setting-late-pct">Late percent (per 30 days overdue)</label>
84	        <input id="setting-late-pct" data-testid="setting-late-pct" formControlName="latePct" inputmode="decimal" />
85	        <label for="setting-late-pct-from">Late percent from (blank: today)</label>
86	        <input id="setting-late-pct-from" data-testid="setting-late-pct-from" type="date" formControlName="latePctFrom" />
87	        <label for="setting-policy-date">Policy date (claims dated before it round half up; blank: today)</label>
88	        <input id="setting-policy-date" data-testid="setting-policy-date" type="date" formControlName="policyDate" />
89	        <label for="setting-period-numbering-from">Period numbering from (claims opened from it are numbered within their period; blank: off)</label>
90	        <input id="setting-period-numbering-from" data-testid="setting-period-numbering-from" type="date"
91	               formControlName="periodNumberingFrom" />
92	        <label for="setting-grace-days">Grace days (a period still open this many days after its end closes when today is changed; blank: off)</label>
93	        <input id="setting-grace-days" data-testid="setting-grace-days" formControlName="graceDays" inputmode="numeric" />
94	        <label for="setting-entry-date">Entry date (a new claim's date when none is given; blank: off, the sheet's today)</label>
95	        <input id="setting-entry-date" data-testid="setting-entry-date" type="date" formControlName="entryDate" />
96	        <label for="setting-pot">Pot (a balanced pool's members cut it by their shares; blank: none)</label>
97	        <input id="setting-pot" data-testid="setting-pot" formControlName="pot" inputmode="decimal" />
98	        <fieldset formGroupName="permissions">
99	          <legend>Permissions (roles that may take each action, comma separated; blank: the standing rule)</legend>
100	          @for (a of permActions; track a) {
101	            <label [for]="'setting-perm-' + a">{{ a }} (blank: {{ standing[a] }})</label>
102	            <input [id]="'setting-perm-' + a" [attr.data-testid]="'setting-perm-' + a" [formControlName]="a" />
103	          }
104	        </fieldset>
105	        <button type="submit" data-testid="settings-save">Save settings</button>
106	        @if (settingsError()) {
107	          <p role="alert" data-testid="settings-error">{{ settingsError() }}</p>
108	        }
109	      </form>
110	      <p>Clerk limit in force: <span data-testid="setting-clerk-limit-current">{{ clerkLimit() ?? '' }}</span></p>
111	      <p>Cap in force: <span data-testid="setting-cap-current">{{ cap() ?? '' }}</span></p>
112	      <p>Proof threshold in force: <span data-testid="setting-proof-threshold-current">{{ proofThreshold() ?? '' }}</span></p>
113	      @for (g of grades; track g) {
114	        <p>Proof threshold in force for grade {{ g }}:
115	          <span [attr.data-testid]="'setting-proof-threshold-' + g + '-current'">{{ gradeProofThresholds()[g] ?? '' }}</span></p>
116	      }
117	      <p>Note threshold in force: <span data-testid="setting-note-threshold-current">{{ noteThreshold() ?? '' }}</span></p>
118	      <p>Floor in force: <span data-testid="setting-floor-current">{{ floor() ?? '' }}</span></p>
119	      <p>Terms in force: <span data-testid="setting-terms-current">{{ terms() ?? '' }}</span></p>
120	      @for (g of grades; track g) {
121	        <p>Terms in force for grade {{ g }}:
122	          <span [attr.data-testid]="'setting-terms-' + g + '-current'">{{ termsOf(g) ?? '' }}</span></p>
123	      }
124	      @for (g of grades; track g) {
125	        <p>Grace days in force for grade {{ g }}:
126	          <span [attr.data-testid]="'setting-grace-' + g + '-current'">{{ gradeGraces()[g] ?? '' }}</span></p>
127	      }
128	      <p>Late percent in force: <span data-testid="setting-late-pct-current">{{ latePct() ?? '' }}</span></p>
129	      <p>Policy date in force: <span data-testid="setting-policy-date-current">{{ policyDate() ?? '' }}</span></p>
130	      <p>Period numbering from: <span data-testid="setting-period-numbering-from-current">{{ periodNumberingFrom() ?? '' }}</span></p>
131	      <p>Grace days: <span data-testid="setting-grace-days-current">{{ graceDays() ?? '' }}</span></p>
132	      <p>Entry date: <span data-testid="setting-entry-date-current">{{ entryDate() ?? '' }}</span></p>
133	      <p>Pot: <span data-testid="setting-pot-current">{{ pot() ?? '' }}</span></p>
134	      @for (a of permActions; track a) {
135	        <p>Roles that may {{ a }}:
136	          <span [attr.data-testid]="'setting-perm-' + a + '-current'">{{ permissions()[a] ?? '' }}</span></p>
137	      }
138	      <h3>Roles</h3>
139	      <form data-testid="role-form" [formGroup]="roleForm" (ngSubmit)="saveRole()">
140	        <label for="role-form-user">User</label>
141	        <input id="role-form-user" data-testid="role-form-user" formControlName="user" />
142	        <label for="role-form-role">Role</label>
143	        <input id="role-form-role" data-testid="role-form-role" formControlName="role" list="role-names" />
144	        <datalist id="role-names">
145	          @for (r of roleNames; track r) {
146	            <option [value]="r"></option>
147	          }
148	        </datalist>
149	        <button type="submit" data-testid="role-form-submit">Set role</button>
150	        @if (roleError()) {
151	          <p role="alert" data-testid="role-form-error">{{ roleError() }}</p>
152	        }
153	      </form>
154	      <table data-testid="roles">
155	        <caption>Roles given (any other name is a clerk)</caption>
156	        <thead>
157	          <tr><th scope="col">User</th><th scope="col">Role</th></tr>
158	        </thead>
159	        <tbody>
160	          @for (r of roles(); track r.user) {
161	            <tr [attr.data-testid]="'role-row-' + r.user">
162	              <th scope="row" data-testid="role-user">{{ r.user }}</th>
163	              <td data-testid="role-value">{{ r.role }}</td>
164	            </tr>
165	          }
166	        </tbody>
167	      </table>
168	    </section>
169	  `,
170	})
171	export class SettingsForm {
172	  private readonly api = inject(SheetSettings);
173	  private readonly session = inject(Session);
174	  private readonly pools = inject(Pools);
175	
176	  protected readonly roleNames = ROLES;
177	  protected readonly clerkLimit = signal<string | null>(null);
178	  protected readonly cap = signal<string | null>(null);
179	  protected readonly proofThreshold = signal<string | null>(null);
180	  protected readonly noteThreshold = signal<string | null>(null);
181	  protected readonly floor = signal<string | null>(null);
182	  protected readonly terms = signal<number | null>(null);
183	  protected readonly grades: Grade[] = ['A', 'B', 'C'];
184	  /** The terms each grade has of its own; a grade not in it takes the sheet's terms. */
185	  protected readonly gradeTerms = signal<Partial<Record<Grade, number>>>({});
186	  /** The grace days each grade has in force; a grade not in it has none. */
187	  protected readonly gradeGraces = signal<Partial<Record<Grade, number>>>({});
188	  /** The proof threshold each grade has of its own in force; a grade not in it takes the sheet's. */
189	  protected readonly gradeProofThresholds = signal<Partial<Record<Grade, string>>>({});
190	  protected readonly latePct = signal<string | null>(null);
191	  protected readonly policyDate = signal<string | null>(null);
192	  protected readonly periodNumberingFrom = signal<string | null>(null);
193	  protected readonly graceDays = signal<number | null>(null);
194	  protected readonly entryDate = signal<string | null>(null);
195	  protected readonly pot = signal<string | null>(null);
196	  protected readonly permActions = PERM_ACTIONS;
197	  protected readonly standing = STANDING_PERMISSIONS;
198	  /** The permission matrix as set; an action's entry is blank when it keeps the standing rule. */
199	  protected readonly permissions = signal<Partial<Record<PermAction, string>>>({});
200	  protected readonly roles = signal<Role[]>([]);
201	  protected readonly settingsError = signal('');
202	  protected readonly roleError = signal('');
203	  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
204	  private submitting = false;
205	  /** Only the newest read of the sheet may show: a load overtaken by another is dropped. */
206	  private reads = 0;
207	  protected readonly settingsForm = new FormGroup({
