210	    cap: new FormControl('', { nonNullable: true }),
211	    capFrom: new FormControl('', { nonNullable: true }),
212	    proofThreshold: new FormControl('', { nonNullable: true }),
213	    proofThresholdFrom: new FormControl('', { nonNullable: true }),
214	    gradeProofThresholds: new FormGroup({
215	      A: new FormControl('', { nonNullable: true }),
216	      AFrom: new FormControl('', { nonNullable: true }),
217	      B: new FormControl('', { nonNullable: true }),
218	      BFrom: new FormControl('', { nonNullable: true }),
219	      C: new FormControl('', { nonNullable: true }),
220	      CFrom: new FormControl('', { nonNullable: true }),
221	    }),
222	    noteThreshold: new FormControl('', { nonNullable: true }),
223	    noteThresholdFrom: new FormControl('', { nonNullable: true }),
224	    floor: new FormControl('', { nonNullable: true }),
225	    floorFrom: new FormControl('', { nonNullable: true }),
226	    terms: new FormControl('', { nonNullable: true }),
227	    termsFrom: new FormControl('', { nonNullable: true }),
228	    gradeTerms: new FormGroup({
229	      A: new FormControl('', { nonNullable: true }),
230	      AFrom: new FormControl('', { nonNullable: true }),
231	      B: new FormControl('', { nonNullable: true }),
232	      BFrom: new FormControl('', { nonNullable: true }),
233	      C: new FormControl('', { nonNullable: true }),
234	      CFrom: new FormControl('', { nonNullable: true }),
235	    }),
236	    gradeGraces: new FormGroup({
237	      A: new FormControl('', { nonNullable: true }),
238	      AFrom: new FormControl('', { nonNullable: true }),
239	      B: new FormControl('', { nonNullable: true }),
240	      BFrom: new FormControl('', { nonNullable: true }),
241	      C: new FormControl('', { nonNullable: true }),
242	      CFrom: new FormControl('', { nonNullable: true }),
243	    }),
244	    latePct: new FormControl('', { nonNullable: true }),
245	    latePctFrom: new FormControl('', { nonNullable: true }),
246	    policyDate: new FormControl('', { nonNullable: true }),
247	    periodNumberingFrom: new FormControl('', { nonNullable: true }),
248	    graceDays: new FormControl('', { nonNullable: true }),
249	    entryDate: new FormControl('', { nonNullable: true }),
250	    pot: new FormControl('', { nonNullable: true }),
251	    permissions: new FormGroup({
252	      open: new FormControl('', { nonNullable: true }),
253	      settle: new FormControl('', { nonNullable: true }),
254	      void: new FormControl('', { nonNullable: true }),
255	      reassign: new FormControl('', { nonNullable: true }),
256	      close: new FormControl('', { nonNullable: true }),
257	      reopen: new FormControl('', { nonNullable: true }),
258	    }),
