265	  constructor() {
266	    this.settingsForm.valueChanges.subscribe(() => this.settingsError.set(''));
267	    this.roleForm.valueChanges.subscribe(() => this.roleError.set(''));
268	    effect(() => {
269	      this.session.loads();
270	      this.session.today(); // what is in force follows the sheet's today
271	      const sheetId = this.session.sheetId();
272	      this.clerkLimit.set(null);
273	      this.cap.set(null);
274	      this.proofThreshold.set(null);
275	      this.noteThreshold.set(null);
276	      this.floor.set(null);
277	      this.terms.set(null);
278	      this.gradeTerms.set({});
279	      this.gradeGraces.set({});
280	      this.gradeProofThresholds.set({});
281	      this.latePct.set(null);
282	      this.policyDate.set(null);
283	      this.periodNumberingFrom.set(null);
284	      this.graceDays.set(null);
285	      this.entryDate.set(null);
286	      this.pot.set(null);
