292	
293	  /** Save the settings changed since the last save (typed into, or entered and left, which an
294	   *  unchanged blank field may be); all of them when none was. */
295	  protected async saveSettings(): Promise<void> {
296	    if (this.submitting) return;
297	    this.settingsError.set('');
298	    const { clerkLimit, clerkLimitFrom, cap, capFrom, proofThreshold, proofThresholdFrom, gradeProofThresholds, noteThreshold, noteThresholdFrom, floor, floorFrom, terms, termsFrom, gradeTerms, gradeGraces, latePct,
299	      latePctFrom, policyDate, periodNumberingFrom, graceDays, entryDate, pot, permissions } = this.settingsForm.controls;
300	    const changed = (...cs: AbstractControl[]) => cs.some((c) => c.dirty || c.touched);
301	    const none = !changed(clerkLimit, clerkLimitFrom) && !changed(cap, capFrom)
302	      && !changed(proofThreshold, proofThresholdFrom) && !changed(gradeProofThresholds) && !changed(noteThreshold, noteThresholdFrom)
303	      && !changed(floor, floorFrom)
304	      && !changed(terms, termsFrom) && !changed(gradeTerms) && !changed(gradeGraces) && !changed(latePct, latePctFrom) && !changed(policyDate)
305	      && !changed(periodNumberingFrom) && !changed(graceDays) && !changed(entryDate) && !changed(pot) && !changed(permissions);
306	    /** A from-date typed, or null when blank (the sheet's today). */
307	    const from = (c: AbstractControl<string>) => c.value.trim() || null;
308	    const fromsToSave: AbstractControl<string>[] = [];
309	    const limitValue = clerkLimit.value.trim();
310	    const capValue = cap.value.trim();
311	    const saveCap = changed(cap, capFrom) || (none && capValue !== '');
312	    const thresholdValue = proofThreshold.value.trim();
313	    const saveThreshold = changed(proofThreshold, proofThresholdFrom) || (none && thresholdValue !== '');
314	    const gradeThresholdsToSave = this.grades
315	      .map((g) => ({
316	        grade: g, control: gradeProofThresholds.controls[g], fromControl: gradeProofThresholds.controls[`${g}From`],
317	        value: gradeProofThresholds.controls[g].value.trim(),
318	      }))
319	      .filter((t) => changed(t.control, t.fromControl) || (none && t.value !== ''));
320	    const noteThresholdValue = noteThreshold.value.trim();
321	    const saveNoteThreshold = changed(noteThreshold, noteThresholdFrom) || (none && noteThresholdValue !== '');
322	    const floorValue = floor.value.trim();
323	    const saveLimit = none || changed(clerkLimit, clerkLimitFrom);
324	    const saveFloor = none || changed(floor, floorFrom);
325	    const termsValue = terms.value.trim();
326	    const saveTerms = none || changed(terms, termsFrom);
327	    const gradeTermsToSave = this.grades
328	      .map((g) => ({
329	        grade: g, control: gradeTerms.controls[g], fromControl: gradeTerms.controls[`${g}From`],
330	        value: gradeTerms.controls[g].value.trim(),
331	      }))
332	      .filter((t) => (none || changed(t.control, t.fromControl)) && t.value !== '');
333	    const gracesToSave = this.grades
334	      .map((g) => ({
335	        grade: g, control: gradeGraces.controls[g], fromControl: gradeGraces.controls[`${g}From`],
336	        value: gradeGraces.controls[g].value.trim(),
337	      }))
338	      .filter((t) => changed(t.control, t.fromControl) || (none && t.value !== ''));
339	    const latePctValue = latePct.value.trim();
340	    const saveLatePct = none || changed(latePct, latePctFrom);
341	    const policyDateValue = policyDate.value.trim();
342	    const savePolicyDate = none || changed(policyDate);
343	    const numberingValue = periodNumberingFrom.value.trim();
344	    const saveNumbering = none || changed(periodNumberingFrom);
345	    const graceValue = graceDays.value.trim();
346	    const saveGrace = changed(graceDays) || (none && graceValue !== '');
347	    const entryDateValue = entryDate.value.trim();
348	    const saveEntryDate = changed(entryDate) || (none && entryDateValue !== '');
349	    const potValue = pot.value.trim();
350	    const savePot = changed(pot) || (none && potValue !== '');
351	    const permsToSave = this.permActions
352	      .map((a) => ({ action: a, control: permissions.controls[a], value: permissions.controls[a].value.trim() }))
353	      .filter((p) => changed(p.control) || (none && p.value !== ''));
354	    if (saveLimit) fromsToSave.push(clerkLimitFrom);
355	    if (saveCap) fromsToSave.push(capFrom);
356	    if (saveThreshold) fromsToSave.push(proofThresholdFrom);
357	    gradeThresholdsToSave.forEach((t) => fromsToSave.push(t.fromControl));
358	    if (saveNoteThreshold) fromsToSave.push(noteThresholdFrom);
359	    if (saveFloor && floorValue !== '') fromsToSave.push(floorFrom);
360	    if (saveTerms && termsValue !== '') fromsToSave.push(termsFrom);
361	    gradeTermsToSave.forEach((t) => fromsToSave.push(t.fromControl));
362	    gracesToSave.forEach((t) => fromsToSave.push(t.fromControl));
363	    if (saveLatePct && latePctValue !== '') fromsToSave.push(latePctFrom);
364	    if (fromsToSave.some((c) => c.value.trim() !== '' && !POLICY_DATE.test(c.value.trim()))) {
365	      this.settingsError.set('Enter a from-date, or leave it blank for the sheet\'s today.');
366	      return;
367	    }
368	    if (saveLimit && limitValue !== '' && !LIMIT.test(limitValue)) {
369	      this.settingsError.set('Enter a clerk limit of 0.00 or more with up to two decimals, or leave it blank for no limit.');
370	      return;
371	    }
372	    if (saveCap && capValue !== '' && !LIMIT.test(capValue)) {
373	      this.settingsError.set('Enter a cap of 0.00 or more with up to two decimals, or leave it blank for no cap.');
374	      return;
375	    }
376	    if (saveThreshold && thresholdValue !== '' && !LIMIT.test(thresholdValue)) {
377	      this.settingsError.set('Enter a proof threshold of 0.00 or more with up to two decimals, or leave it blank for none.');
378	      return;
379	    }
380	    if (gradeThresholdsToSave.some((t) => t.value !== '' && !LIMIT.test(t.value))) {
381	      this.settingsError.set('Enter a proof threshold for a grade of 0.00 or more with up to two decimals, or leave it blank for the sheet\'s.');
382	      return;
383	    }
384	    if (saveNoteThreshold && noteThresholdValue !== '' && !LIMIT.test(noteThresholdValue)) {
385	      this.settingsError.set('Enter a note threshold of 0.00 or more with up to two decimals, or leave it blank for none.');
386	      return;
387	    }
388	    if (saveFloor && !(none && floorValue === '') && !LIMIT.test(floorValue)) {
389	      this.settingsError.set('Enter a floor of 0.00 or more with up to two decimals.');
390	      return;
391	    }
392	    if (saveTerms && !(none && termsValue === '') && !TERMS.test(termsValue)) {
393	      this.settingsError.set('Enter terms of 0 or more whole days.');
394	      return;
395	    }
396	    if (gradeTermsToSave.some((t) => !TERMS.test(t.value))) {
397	      this.settingsError.set('Enter terms for a grade of 0 or more whole days, or leave them blank.');
398	      return;
399	    }
400	    if (gracesToSave.some((t) => t.value !== '' && !TERMS.test(t.value))) {
401	      this.settingsError.set('Enter grace days for a grade of 0 or more whole days, or leave them blank for none.');
402	      return;
403	    }
404	    if (saveLatePct && !(none && latePctValue === '') && !LATE_PCT.test(latePctValue)) {
405	      this.settingsError.set('Enter a late percent of 0.00 or more with up to two decimals.');
406	      return;
407	    }
408	    if (savePolicyDate && policyDateValue !== '' && !POLICY_DATE.test(policyDateValue)) {
409	      this.settingsError.set('Enter a policy date, or leave it blank for the sheet\'s today.');
410	      return;
411	    }
412	    if (saveNumbering && numberingValue !== '' && !POLICY_DATE.test(numberingValue)) {
413	      this.settingsError.set('Enter a period numbering from date, or leave it blank for off.');
414	      return;
415	    }
416	    if (saveGrace && graceValue !== '' && !TERMS.test(graceValue)) {
417	      this.settingsError.set('Enter grace days of 0 or more whole days, or leave them blank for off.');
418	      return;
419	    }
420	    if (saveEntryDate && entryDateValue !== '' && !POLICY_DATE.test(entryDateValue)) {
421	      this.settingsError.set('Enter an entry date, or leave it blank for off.');
422	      return;
423	    }
424	    if (savePot && potValue !== '' && !LIMIT.test(potValue)) {
425	      this.settingsError.set('Enter a pot of 0.00 or more with up to two decimals, or leave it blank for none.');
426	      return;
427	    }
428	    if (permsToSave.some((p) => p.value !== '' && !PERM_ROLES.test(p.value))) {
429	      this.settingsError.set('Enter the roles that may take an action as clerk, steward or both, comma separated, or leave it blank for the standing rule.');
430	      return;
431	    }
432	    this.submitting = true;
433	    try {
434	      if (saveLimit) {
435	        const saved = await this.api.setClerkLimit(limitValue === '' ? null : limitValue, from(clerkLimitFrom));
436	        this.clerkLimit.set(saved.clerkLimit);
437	        for (const c of [clerkLimit, clerkLimitFrom]) {
438	          c.markAsPristine();
439	          c.markAsUntouched();
440	        }
441	      }
442	      if (saveCap) {
443	        const saved = await this.api.setCap(capValue === '' ? null : capValue, from(capFrom));
444	        this.cap.set(saved.cap);
445	        for (const c of [cap, capFrom]) {
446	          c.markAsPristine();
447	          c.markAsUntouched();
448	        }
449	      }
450	      if (saveThreshold) {
451	        const saved = await this.api.setProofThreshold(thresholdValue === '' ? null : thresholdValue,
452	          from(proofThresholdFrom));
453	        this.proofThreshold.set(saved.proofThreshold);
454	        for (const c of [proofThreshold, proofThresholdFrom]) {
455	          c.markAsPristine();
456	          c.markAsUntouched();
457	        }
458	      }
459	      for (const t of gradeThresholdsToSave) {
460	        const saved = await this.api.setGradeProofThreshold(t.grade, t.value === '' ? null : t.value,
461	          from(t.fromControl));
462	        this.gradeProofThresholds.set(saved.gradeProofThresholds);
463	        for (const c of [t.control, t.fromControl]) {
464	          c.markAsPristine();
465	          c.markAsUntouched();
466	        }
467	      }
468	      if (saveNoteThreshold) {
469	        const saved = await this.api.setNoteThreshold(noteThresholdValue === '' ? null : noteThresholdValue,
470	          from(noteThresholdFrom));
471	        this.noteThreshold.set(saved.noteThreshold);
472	        for (const c of [noteThreshold, noteThresholdFrom]) {
473	          c.markAsPristine();
474	          c.markAsUntouched();
475	        }
476	      }
477	      if (saveFloor && floorValue !== '') {
478	        const saved = await this.api.setFloor(floorValue, from(floorFrom));
479	        this.floor.set(saved.floor);
480	        for (const c of [floor, floorFrom]) {
481	          c.markAsPristine();
482	          c.markAsUntouched();
483	        }
484	      }
485	      if (saveTerms && termsValue !== '') {
486	        const saved = await this.api.setTerms(termsValue, from(termsFrom));
487	        this.terms.set(saved.terms);
488	        for (const c of [terms, termsFrom]) {
489	          c.markAsPristine();
490	          c.markAsUntouched();
491	        }
492	      }
493	      for (const t of gradeTermsToSave) {
494	        const saved = await this.api.setGradeTerms(t.grade, t.value, from(t.fromControl));
495	        this.gradeTerms.set(saved.gradeTerms);
496	        for (const c of [t.control, t.fromControl]) {
497	          c.markAsPristine();
498	          c.markAsUntouched();
499	        }
500	      }
501	      for (const t of gracesToSave) {
502	        const saved = await this.api.setGrace(t.grade, t.value === '' ? null : t.value, from(t.fromControl));
503	        this.gradeGraces.set(saved.gradeGraces);
504	        for (const c of [t.control, t.fromControl]) {
505	          c.markAsPristine();
506	          c.markAsUntouched();
507	        }
508	      }
509	      if (saveLatePct && latePctValue !== '') {
510	        const saved = await this.api.setLatePct(latePctValue, from(latePctFrom));
511	        this.latePct.set(saved.latePct);
512	        for (const c of [latePct, latePctFrom]) {
513	          c.markAsPristine();
514	          c.markAsUntouched();
515	        }
516	      }
517	      if (savePolicyDate) {
518	        const saved = await this.api.setPolicyDate(policyDateValue === '' ? null : policyDateValue);
519	        this.policyDate.set(saved.policyDate);
520	        policyDate.markAsPristine();
521	        policyDate.markAsUntouched();
522	      }
523	      if (saveNumbering) {
524	        const saved = await this.api.setPeriodNumberingFrom(numberingValue === '' ? null : numberingValue);
525	        this.periodNumberingFrom.set(saved.periodNumberingFrom);
526	        periodNumberingFrom.markAsPristine();
527	        periodNumberingFrom.markAsUntouched();
528	      }
529	      if (saveGrace) {
530	        const saved = await this.api.setGraceDays(graceValue === '' ? null : graceValue);
531	        this.graceDays.set(saved.graceDays);
532	        graceDays.markAsPristine();
533	        graceDays.markAsUntouched();
534	      }
535	      if (saveEntryDate) {
536	        const saved = await this.api.setEntryDate(entryDateValue === '' ? null : entryDateValue);
537	        this.entryDate.set(saved.entryDate);
538	        entryDate.markAsPristine();
539	        entryDate.markAsUntouched();
540	      }
541	      if (savePot) {
542	        const saved = await this.api.setPot(potValue === '' ? null : potValue);
543	        this.pot.set(saved.pot);
544	        pot.markAsPristine();
545	        pot.markAsUntouched();
546	        this.pools.refresh();
547	      }
548	      for (const p of permsToSave) {
549	        const saved = await this.api.setPermission(p.action, p.value === '' ? null : p.value);
550	        this.permissions.set(saved.permissions);
551	        p.control.markAsPristine();
552	        p.control.markAsUntouched();
553	      }
554	      // a blank field entered and left, and not saved, is not taken as changed by the next save
555	      this.settingsForm.markAsUntouched();
556	    } catch {
557	      this.settingsError.set('The settings could not be saved.');
558	    } finally {
559	      this.submitting = false;
560	    }
561	  }
562	
563	  /** The terms in force for a grade: its own, or else the sheet's. */
564	  protected termsOf(g: Grade): number | null {
565	    return this.gradeTerms()[g] ?? this.terms();
566	  }
567	
568	  protected async saveRole(): Promise<void> {
569	    if (this.submitting) return;
570	    this.roleError.set('');
571	    const user = this.roleForm.getRawValue().user.trim();
572	    const role = this.roleForm.getRawValue().role.trim();
573	    if (user === '') {
574	      this.roleError.set('Enter a user name.');
575	      return;
576	    }
577	    if (!(ROLES as string[]).includes(role)) {
578	      this.roleError.set('Choose a role of clerk, steward or viewer.');
579	      return;
580	    }
581	    this.submitting = true;
582	    try {
583	      const saved = await this.api.setRole(user, role as RoleName);
584	      this.roles.update((rs) =>
585	        [...rs.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
586	      );
587	      this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
588	    } catch {
589	      this.roleError.set('The role could not be set.');
590	    } finally {
591	      this.submitting = false;
592	    }
593	  }
594	
595	  private async reload(sheetId: string): Promise<void> {
596	    const read = ++this.reads;
597	    try {
598	      const [settings, roles] = await Promise.all([this.api.get(sheetId), this.api.roles(sheetId)]);
599	      if (read === this.reads) {
600	        this.clerkLimit.set(settings.clerkLimit);
601	        this.cap.set(settings.cap);
602	        this.proofThreshold.set(settings.proofThreshold);
603	        this.noteThreshold.set(settings.noteThreshold);
604	        this.floor.set(settings.floor);
605	        this.terms.set(settings.terms);
606	        this.gradeTerms.set(settings.gradeTerms);
607	        this.gradeGraces.set(settings.gradeGraces);
608	        this.gradeProofThresholds.set(settings.gradeProofThresholds);
609	        this.latePct.set(settings.latePct);
610	        this.policyDate.set(settings.policyDate);
611	        this.periodNumberingFrom.set(settings.periodNumberingFrom);
612	        this.graceDays.set(settings.graceDays);
613	        this.entryDate.set(settings.entryDate);
614	        this.pot.set(settings.pot);
615	        this.permissions.set(settings.permissions);
616	        this.roles.set(roles);
617	      }
618	    } catch {
619	      // the settings stay blank; the next load reads them again
620	    }
621	  }
622	}
