import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SignedIn {
  name: string;
}

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
}

// Who is signed in and which sheet is active. Everything else in the app is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd) as the store holds it. */
  readonly sheetToday = signal<string | null>(null);
  /** The day (yyyy-mm-dd) this user's screen shows every sheet as it stood at the end of; null when
   *  it shows the sheet as it is now. While it is set every change is refused. */
  readonly asOf = signal<string | null>(null);
  /** The day every date decision and default date uses: the as-of day when one is set, or else the
   *  sheet's today. */
  readonly today = computed(() => this.asOf() ?? this.sheetToday());
  /** Whether the active sheet is archived: it stays visible and refuses every change. */
  readonly archived = signal(false);
  /** The sheet whose people and claims are on screen: set once a load of them has been read, so the
   *  sheet shows as loaded only when its rows are there to act on. */
  readonly shownId = signal<string | null>(null);
  /** Bumped on every sheet load, so what is kept per sheet is re-read from the store. */
  readonly loads = signal(0);

  async signIn(name: string): Promise<void> {
    const res = await firstValueFrom(this.http.post<SignedIn>('/api/signin', { name }));
    this.user.set(res.name);
    this.sheetId.set(null);
    this.shownId.set(null);
    this.sheetToday.set(null);
    this.asOf.set(null);
    this.archived.set(false);
  }

  /** Record that the sheet's people and claims, as read for its latest load, are on screen. */
  markShown(id: string): void {
    if (this.sheetId() === id) this.shownId.set(id);
  }

  /** Load a sheet by id; one never loaded before starts empty. */
  async loadSheet(id: string): Promise<void> {
    const user = this.user();
    if (!user) throw new Error('not signed in');
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: { 'X-User': user },
      }),
    );
    this.show(res);
    this.bumpLoads();
  }

  /** Change the active sheet's today. */
  async setToday(today: string): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': user },
      }),
    );
    this.show(res);
  }

  /** Archive the active sheet (a steward only). */
  async archive(): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
        headers: { 'X-User': user },
      }),
    );
    this.show(res);
  }

  /** Show every sheet as it stood at the end of a day (null: as it is now), re-reading it. */
  setAsOf(day: string | null): void {
    this.asOf.set(day);
    this.bumpLoads();
  }

  private show(sheet: SheetView): void {
    this.sheetId.set(sheet.id);
    this.sheetToday.set(sheet.today);
    this.archived.set(sheet.archived);
  }

  private bumpLoads(): void {
    this.loads.update((n) => n + 1);
  }
}
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';

// The signed-in name, and the form that loads a sheet by id.
@Component({
  selector: 'app-sheet-bar',
  imports: [ReactiveFormsModule],
  template: `
    <p>Signed in as <strong data-testid="current-user">{{ session.user() }}</strong></p>
    <form data-testid="sheet-form" [formGroup]="form" (ngSubmit)="load()">
      <label for="sheet-id-input">Sheet id</label>
      <input id="sheet-id-input" data-testid="sheet-id-input" formControlName="sheetId" />
      <button type="submit" data-testid="sheet-load">Load sheet</button>
      @if (error()) {
        <p role="alert" data-testid="sheet-load-error">{{ error() }}</p>
      }
    </form>
    <p>Sheet: <strong data-testid="sheet-current-id">{{ session.shownId() ?? '' }}</strong></p>
    @if (session.sheetId()) {
      <p>Today: <strong data-testid="sheet-today">{{ session.sheetToday() ?? '' }}</strong></p>
      <form data-testid="sheet-today-form" [formGroup]="todayForm" (ngSubmit)="saveToday()">
        <label for="sheet-today-input">Sheet's today</label>
        <input id="sheet-today-input" type="date" data-testid="sheet-today-input" formControlName="today" />
        <button type="submit" data-testid="sheet-today-save">Set today</button>
      </form>
      <p>Archived: <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong></p>
      <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
      @if (sheetError()) {
        <p role="alert" data-testid="sheet-error">{{ sheetError() }}</p>
      }
      <form data-testid="asof-form" [formGroup]="asOfForm" (ngSubmit)="setAsOf()">
        <label for="asof-date">Show the sheet as of</label>
        <input id="asof-date" type="date" data-testid="asof-date" formControlName="day" />
        <button type="submit" data-testid="asof-set">Set as of</button>
        <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
        @if (asOfError()) {
          <p role="alert" data-testid="asof-error">{{ asOfError() }}</p>
        }
      </form>
      <p>As of: <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></p>
    }
  `,
})
export class SheetBar {
  protected readonly session = inject(Session);
  protected readonly form = new FormGroup({ sheetId: new FormControl('', { nonNullable: true }) });
  protected readonly error = signal('');
  protected readonly todayForm = new FormGroup({ today: new FormControl('', { nonNullable: true }) });
  protected readonly sheetError = signal('');
  protected readonly asOfForm = new FormGroup({ day: new FormControl('', { nonNullable: true }) });
  protected readonly asOfError = signal('');

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    this.todayForm.valueChanges.subscribe(() => this.sheetError.set(''));
    this.asOfForm.valueChanges.subscribe(() => this.asOfError.set(''));
  }

  /** Show the sheet, on this screen only, as it stood at the end of the day entered. */
  setAsOf(): void {
    this.asOfError.set('');
    this.sheetError.set('');
    const day = this.asOfForm.controls.day.value.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) {
      this.asOfError.set('Enter a date to show the sheet as of.');
      return;
    }
    this.session.setAsOf(day);
  }

  /** Show the sheet as it is now again. */
  clearAsOf(): void {
    this.asOfError.set('');
    this.sheetError.set('');
    this.asOfForm.controls.day.setValue('', { emitEvent: false });
    this.session.setAsOf(null);
  }

  async load(): Promise<void> {
    this.error.set('');
    const id = this.form.controls.sheetId.value.trim();
    if (!id) {
      this.error.set('Enter a sheet id to load.');
      return;
    }
    this.sheetError.set('');
    try {
      await this.session.loadSheet(id);
    } catch {
      this.error.set('The sheet could not be loaded.');
    }
  }

  async saveToday(): Promise<void> {
    this.sheetError.set('');
    const today = this.todayForm.controls.today.value.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.sheetError.set('Enter a date for the sheet\'s today.');
      return;
    }
    try {
      await this.session.setToday(today);
    } catch {
      this.sheetError.set('The sheet\'s today could not be changed.');
    }
  }

  async archive(): Promise<void> {
    this.sheetError.set('');
    try {
      await this.session.archive();
    } catch {
      this.sheetError.set('The sheet could not be archived.');
    }
  }
}
package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import net.officefloor.hq.app.role.ViewerAllowed;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class SheetController {

    /** What the screen shows of a loaded sheet. */
    public record SheetView(String id, LocalDate today, boolean archived) {
        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.isArchived());
        }
    }

    /** A change of the sheet's today. */
    public record TodayChange(@NotNull LocalDate today) {
    }

    private final SheetService service;

    public SheetController(SheetService service) {
        this.service = service;
    }

    /** Load a sheet by id, starting it empty if it was never loaded before. */
    @ViewerAllowed
    @ArchivedAllowed
    @AsOfAllowed
    @PostMapping("/{id}/load")
    public SheetView load(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return SheetView.of(service.load(id.trim(), user.trim()));
    }

    /** Change the sheet's today. */
    @PutMapping("/{id}/today")
    public SheetView setToday(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody TodayChange change) {
        return SheetView.of(service.setToday(id.trim(), user.trim(), change.today()));
    }

    /** Archive the sheet; only a steward may. */
    @PostMapping("/{id}/archive")
    public SheetView archive(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return SheetView.of(service.archive(id.trim(), user.trim()));
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade } from './people';
import { Session } from './session';

// The dated settings (the clerk limit, the cap, the floor, the terms and the late percent) as in force
// on the sheet's today.
export interface Settings {
  /** The most due a clerk may settle, as text with two decimals; null when there is no limit. */
  clerkLimit: string | null;
  /** The least live due a claim has, as text with two decimals. */
  floor: string;
  /** The days after its date a claim is due by. */
  terms: number;
  /** The percent of its figure an overdue claim gains for every full 30 days, as text with two decimals. */
  latePct: string;
  /** The policy date (yyyy-mm-dd); null when blank, the sheet's today then stands in. */
  policyDate: string | null;
  /** The period numbering from date (yyyy-mm-dd); null when blank (off). */
  periodNumberingFrom: string | null;
  /** The terms each grade has of its own, by grade; a grade not in it takes the sheet's terms. */
  gradeTerms: Partial<Record<Grade, number>>;
  /** The most a person's due-total comes to, as text with two decimals; null when there is no cap. */
  cap: string | null;
  /** The floors recorded, each from its from-date, earliest first. */
  floors: DatedValue[];
  /** The late percents recorded, each from its from-date, earliest first. */
  latePcts: DatedValue[];
  /** The caps recorded (null: no cap), each from its from-date, earliest first. */
  caps: DatedValue<string | null>[];
  /** The due above which a claim needs a proof before it is settled or approved, as text with two
   *  decimals; null when there is none. */
  proofThreshold: string | null;
  /** The due above which a claim cannot be opened with an empty note, as text with two decimals;
   *  null when there is none. */
  noteThreshold: string | null;
  /** The permission matrix: for each action, the comma separated roles that may take it; blank when
   *  it keeps the standing rule. */
  permissions: Record<PermAction, string>;
  /** The grace days: when the sheet's today is changed, an open period whose to-date plus them is
   *  before it is closed; null when blank (off). */
  graceDays: number | null;
  /** The entry date (yyyy-mm-dd): while it is set, a new claim's date when none is given; null when
   *  blank (off, the sheet's today then stands in). */
  entryDate: string | null;
  /** The grace days each grade has in force on the sheet's today, by grade; a grade not in it has
   *  none. */
  gradeGraces: Partial<Record<Grade, number>>;
  /** The grace days recorded for each grade (null: blank, none), each from its from-date, earliest
   *  first. */
  graces: Graces;
  /** The proof threshold each grade has of its own in force on the sheet's today, as text with two
   *  decimals, by grade; a grade not in it takes the sheet's. */
  gradeProofThresholds: Partial<Record<Grade, string>>;
  /** The pot a balanced pool's members cut by their shares, as text with two decimals; null when
   *  blank (none). Not dated. */
  pot: string | null;
}

  }

  /** Set the entry date; null for blank (off). */
  setEntryDate(value: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/entry-date`, { value }, { headers }));
  }

  /** Set the pot; null for blank (none). */
  setPot(value: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/pot`, { value }, { headers }));
  }

  /** Set the roles (comma separated; null for blank, the standing rule) that may take an action. */
  setPermission(action: PermAction, value: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(
      this.http.put<Settings>(`${this.url(sheetId)}/settings/permissions/${action}`, { value }, { headers }),
    );
  }

